```sql
-- ============================================================
-- CISO EXCURSÕES
-- Initial Database Schema
--
-- Migration: 001
-- Description: Initial relational schema for the Ciso Excursões
--              modular monolith.
--
-- UUIDs are generated by the application.
-- Monetary values use NUMERIC(12,2).
-- Business statuses use VARCHAR + CHECK instead of PostgreSQL ENUM.
-- ============================================================


-- ============================================================
-- 1. PERSON
-- ============================================================

CREATE TABLE person (
    id UUID PRIMARY KEY,

    full_name VARCHAR(150) NOT NULL,

    document VARCHAR(20) NOT NULL,

    birth_date DATE NOT NULL,

    phone VARCHAR(20),

    email VARCHAR(254),

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT uq_person_document
        UNIQUE (document)
);


-- ============================================================
-- 2. EXCURSION
-- ============================================================

CREATE TABLE excursion (
    id UUID PRIMARY KEY,

    name VARCHAR(150) NOT NULL,

    destination VARCHAR(150) NOT NULL,

    start_date DATE NOT NULL,

    end_date DATE NOT NULL,

    reference_price NUMERIC(12,2) NOT NULL,

    status VARCHAR(20) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT ck_excursion_dates
        CHECK (end_date >= start_date),

    CONSTRAINT ck_excursion_reference_price
        CHECK (reference_price >= 0),

    CONSTRAINT ck_excursion_status
        CHECK (
            status IN (
                'DRAFT',
                'OPEN',
                'CONFIRMED',
                'IN_PROGRESS',
                'FINISHED',
                'CANCELLED'
            )
        )
);


-- ============================================================
-- 3. BUS TYPE
-- ============================================================

CREATE TABLE bus_type (
    id UUID PRIMARY KEY,

    name VARCHAR(100) NOT NULL,

    capacity INTEGER NOT NULL,

    description VARCHAR(255),

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT ck_bus_type_capacity
        CHECK (capacity > 0)
);


-- ============================================================
-- 4. HOTEL
-- ============================================================

CREATE TABLE hotel (
    id UUID PRIMARY KEY,

    name VARCHAR(150) NOT NULL,

    address VARCHAR(255),

    phone VARCHAR(20),

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL
);


-- ============================================================
-- 5. SUPPLIER
-- ============================================================

CREATE TABLE supplier (
    id UUID PRIMARY KEY,

    name VARCHAR(150) NOT NULL,

    document VARCHAR(20),

    phone VARCHAR(20),

    email VARCHAR(254),

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT uq_supplier_document
        UNIQUE (document)
);


-- ============================================================
-- 6. EXCURSION BUS
--
-- Represents the quantity of a given BusType contracted for
-- a specific excursion.
--
-- Example:
-- Double Deck 64 seats -> quantity = 2
--
-- Individual buses are represented by excursion_vehicle.
-- ============================================================

CREATE TABLE excursion_bus (
    id UUID PRIMARY KEY,

    excursion_id UUID NOT NULL,

    bus_type_id UUID NOT NULL,

    quantity INTEGER NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_excursion_bus_excursion
        FOREIGN KEY (excursion_id)
        REFERENCES excursion (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_excursion_bus_bus_type
        FOREIGN KEY (bus_type_id)
        REFERENCES bus_type (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_excursion_bus_quantity
        CHECK (quantity > 0),

    CONSTRAINT uq_excursion_bus_type
        UNIQUE (excursion_id, bus_type_id)
);


-- ============================================================
-- 7. EXCURSION HOTEL
-- ============================================================

CREATE TABLE excursion_hotel (
    id UUID PRIMARY KEY,

    excursion_id UUID NOT NULL,

    hotel_id UUID NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_excursion_hotel_excursion
        FOREIGN KEY (excursion_id)
        REFERENCES excursion (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_excursion_hotel_hotel
        FOREIGN KEY (hotel_id)
        REFERENCES hotel (id)
        ON DELETE RESTRICT,

    CONSTRAINT uq_excursion_hotel
        UNIQUE (excursion_id, hotel_id)
);


-- ============================================================
-- 8. ACTIVITY
-- ============================================================

CREATE TABLE activity (
    id UUID PRIMARY KEY,

    excursion_id UUID NOT NULL,

    name VARCHAR(150) NOT NULL,

    description VARCHAR(500),

    is_optional BOOLEAN NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_activity_excursion
        FOREIGN KEY (excursion_id)
        REFERENCES excursion (id)
        ON DELETE RESTRICT,

    CONSTRAINT uq_activity_name
        UNIQUE (excursion_id, name)
);


-- ============================================================
-- 9. EXCURSION VEHICLE
--
-- Represents one operational bus.
--
-- Example:
-- ExcursionBus:
--   Double Deck / quantity = 2
--
-- ExcursionVehicle:
--   Ônibus 1
--   Ônibus 2
-- ============================================================

CREATE TABLE excursion_vehicle (
    id UUID PRIMARY KEY,

    excursion_bus_id UUID NOT NULL,

    identifier VARCHAR(50) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_excursion_vehicle_excursion_bus
        FOREIGN KEY (excursion_bus_id)
        REFERENCES excursion_bus (id)
        ON DELETE RESTRICT,

    CONSTRAINT uq_excursion_vehicle_identifier
        UNIQUE (excursion_bus_id, identifier)
);


-- ============================================================
-- 10. ROOM
-- ============================================================

CREATE TABLE room (
    id UUID PRIMARY KEY,

    excursion_hotel_id UUID NOT NULL,

    identifier VARCHAR(30) NOT NULL,

    capacity INTEGER NOT NULL,

    cost NUMERIC(12,2) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_room_excursion_hotel
        FOREIGN KEY (excursion_hotel_id)
        REFERENCES excursion_hotel (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_room_capacity
        CHECK (capacity > 0),

    CONSTRAINT ck_room_cost
        CHECK (cost >= 0),

    CONSTRAINT uq_room_identifier
        UNIQUE (excursion_hotel_id, identifier)
);


-- ============================================================
-- 11. TICKET TYPE
-- ============================================================

CREATE TABLE ticket_type (
    id UUID PRIMARY KEY,

    activity_id UUID NOT NULL,

    name VARCHAR(100) NOT NULL,

    description VARCHAR(255),

    current_price NUMERIC(12,2) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_ticket_type_activity
        FOREIGN KEY (activity_id)
        REFERENCES activity (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_ticket_type_current_price
        CHECK (current_price >= 0),

    CONSTRAINT uq_ticket_type_name
        UNIQUE (activity_id, name)
);


-- ============================================================
-- 12. PARTICIPATION
--
-- Represents a person's participation in one excursion.
--
-- Transport and room are nullable because they may be assigned
-- after the participation is created.
-- ============================================================

CREATE TABLE participation (
    id UUID PRIMARY KEY,

    person_id UUID NOT NULL,

    excursion_id UUID NOT NULL,

    contracted_amount NUMERIC(12,2) NOT NULL,

    status VARCHAR(20) NOT NULL,

    excursion_vehicle_id UUID,

    seat_number INTEGER,

    room_id UUID,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_participation_person
        FOREIGN KEY (person_id)
        REFERENCES person (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_participation_excursion
        FOREIGN KEY (excursion_id)
        REFERENCES excursion (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_participation_excursion_vehicle
        FOREIGN KEY (excursion_vehicle_id)
        REFERENCES excursion_vehicle (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_participation_room
        FOREIGN KEY (room_id)
        REFERENCES room (id)
        ON DELETE RESTRICT,

    CONSTRAINT uq_participation_person_excursion
        UNIQUE (person_id, excursion_id),

    CONSTRAINT ck_participation_contracted_amount
        CHECK (contracted_amount >= 0),

    CONSTRAINT ck_participation_status
        CHECK (
            status IN (
                'ACTIVE',
                'CANCELLED'
            )
        ),

    CONSTRAINT ck_participation_seat_requires_vehicle
        CHECK (
            seat_number IS NULL
            OR excursion_vehicle_id IS NOT NULL
        ),

    CONSTRAINT ck_participation_seat_number
        CHECK (
            seat_number IS NULL
            OR seat_number > 0
        )
);


-- ============================================================
-- 13. TICKET PURCHASE
-- ============================================================

CREATE TABLE ticket_purchase (
    id UUID PRIMARY KEY,

    participation_id UUID NOT NULL,

    ticket_type_id UUID NOT NULL,

    quantity INTEGER NOT NULL,

    sold_price NUMERIC(12,2) NOT NULL,

    status VARCHAR(20) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_ticket_purchase_participation
        FOREIGN KEY (participation_id)
        REFERENCES participation (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_ticket_purchase_ticket_type
        FOREIGN KEY (ticket_type_id)
        REFERENCES ticket_type (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_ticket_purchase_quantity
        CHECK (quantity > 0),

    CONSTRAINT ck_ticket_purchase_sold_price
        CHECK (sold_price >= 0),

    CONSTRAINT ck_ticket_purchase_status
        CHECK (
            status IN (
                'REQUESTED',
                'CONFIRMED'
            )
        )
);


-- ============================================================
-- 14. TICKET SUPPLIER PURCHASE
-- ============================================================

CREATE TABLE ticket_supplier_purchase (
    id UUID PRIMARY KEY,

    supplier_id UUID NOT NULL,

    ticket_type_id UUID NOT NULL,

    quantity INTEGER NOT NULL,

    unit_cost NUMERIC(12,2) NOT NULL,

    status VARCHAR(20) NOT NULL,

    purchase_date DATE NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_ticket_supplier_purchase_supplier
        FOREIGN KEY (supplier_id)
        REFERENCES supplier (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_ticket_supplier_purchase_ticket_type
        FOREIGN KEY (ticket_type_id)
        REFERENCES ticket_type (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_ticket_supplier_purchase_quantity
        CHECK (quantity > 0),

    CONSTRAINT ck_ticket_supplier_purchase_unit_cost
        CHECK (unit_cost >= 0),

    CONSTRAINT ck_ticket_supplier_purchase_status
        CHECK (
            status IN (
                'REQUESTED',
                'CONFIRMED'
            )
        )
);


-- ============================================================
-- 15. PAYMENT
--
-- A payment must belong to exactly one financial target:
--
--   participation       -> excursion package
--   ticket_purchase    -> ticket/activity
-- ============================================================

CREATE TABLE payment (
    id UUID PRIMARY KEY,

    participation_id UUID,

    ticket_purchase_id UUID,

    amount NUMERIC(12,2) NOT NULL,

    payment_date DATE NOT NULL,

    method VARCHAR(20) NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_payment_participation
        FOREIGN KEY (participation_id)
        REFERENCES participation (id)
        ON DELETE RESTRICT,

    CONSTRAINT fk_payment_ticket_purchase
        FOREIGN KEY (ticket_purchase_id)
        REFERENCES ticket_purchase (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_payment_amount
        CHECK (amount > 0),

    CONSTRAINT ck_payment_method
        CHECK (
            method IN (
                'CASH',
                'PIX',
                'CARD'
            )
        ),

    CONSTRAINT ck_payment_exactly_one_target
        CHECK (
            (
                participation_id IS NOT NULL
                AND ticket_purchase_id IS NULL
            )
            OR
            (
                participation_id IS NULL
                AND ticket_purchase_id IS NOT NULL
            )
        )
);


-- ============================================================
-- 16. REFUND
-- ============================================================

CREATE TABLE refund (
    id UUID PRIMARY KEY,

    payment_id UUID NOT NULL,

    amount NUMERIC(12,2) NOT NULL,

    refund_date DATE NOT NULL,

    reason VARCHAR(255),

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_refund_payment
        FOREIGN KEY (payment_id)
        REFERENCES payment (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_refund_amount
        CHECK (amount > 0)
);


-- ============================================================
-- 17. EXPENSE
-- ============================================================

CREATE TABLE expense (
    id UUID PRIMARY KEY,

    excursion_id UUID NOT NULL,

    description VARCHAR(255) NOT NULL,

    category VARCHAR(30) NOT NULL,

    amount NUMERIC(12,2) NOT NULL,

    expense_date DATE NOT NULL,

    created_at TIMESTAMPTZ NOT NULL,

    updated_at TIMESTAMPTZ NOT NULL,

    CONSTRAINT fk_expense_excursion
        FOREIGN KEY (excursion_id)
        REFERENCES excursion (id)
        ON DELETE RESTRICT,

    CONSTRAINT ck_expense_amount
        CHECK (amount > 0),

    CONSTRAINT ck_expense_category
        CHECK (
            category IN (
                'TRANSPORT',
                'ACCOMMODATION',
                'TICKET',
                'FOOD',
                'SOUVENIR',
                'INSURANCE',
                'OTHER'
            )
        )
);


-- ============================================================
-- INDEXES
-- ============================================================

-- Participation
CREATE INDEX idx_participation_person_id
    ON participation (person_id);

CREATE INDEX idx_participation_excursion_id
    ON participation (excursion_id);

CREATE INDEX idx_participation_excursion_vehicle_id
    ON participation (excursion_vehicle_id);

CREATE INDEX idx_participation_room_id
    ON participation (room_id);


-- Excursion transport
CREATE INDEX idx_excursion_bus_excursion_id
    ON excursion_bus (excursion_id);

CREATE INDEX idx_excursion_bus_bus_type_id
    ON excursion_bus (bus_type_id);

CREATE INDEX idx_excursion_vehicle_excursion_bus_id
    ON excursion_vehicle (excursion_bus_id);


-- Accommodation
CREATE INDEX idx_excursion_hotel_excursion_id
    ON excursion_hotel (excursion_id);

CREATE INDEX idx_excursion_hotel_hotel_id
    ON excursion_hotel (hotel_id);

CREATE INDEX idx_room_excursion_hotel_id
    ON room (excursion_hotel_id);


-- Activities and tickets
CREATE INDEX idx_activity_excursion_id
    ON activity (excursion_id);

CREATE INDEX idx_ticket_type_activity_id
    ON ticket_type (activity_id);

CREATE INDEX idx_ticket_purchase_participation_id
    ON ticket_purchase (participation_id);

CREATE INDEX idx_ticket_purchase_ticket_type_id
    ON ticket_purchase (ticket_type_id);


-- Supplier purchases
CREATE INDEX idx_ticket_supplier_purchase_supplier_id
    ON ticket_supplier_purchase (supplier_id);

CREATE INDEX idx_ticket_supplier_purchase_ticket_type_id
    ON ticket_supplier_purchase (ticket_type_id);


-- Payments
CREATE INDEX idx_payment_participation_id
    ON payment (participation_id);

CREATE INDEX idx_payment_ticket_purchase_id
    ON payment (ticket_purchase_id);


-- Refunds
CREATE INDEX idx_refund_payment_id
    ON refund (payment_id);


-- Expenses
CREATE INDEX idx_expense_excursion_id
    ON expense (excursion_id);


-- ============================================================
-- BUSINESS INTEGRITY INDEXES
-- ============================================================

-- Prevents two active participants from occupying the same seat
-- in the same operational vehicle.
--
-- The same seat number can exist in different vehicles.
CREATE UNIQUE INDEX uq_participation_active_vehicle_seat
    ON participation (excursion_vehicle_id, seat_number)
    WHERE status = 'ACTIVE'
      AND seat_number IS NOT NULL;
```
